-- Frozen v0.11.1 schema and its applied additive migration; synthetic upgrade tests only.

CREATE OR REPLACE FUNCTION instr(haystack TEXT, needle TEXT) RETURNS INTEGER
  LANGUAGE SQL IMMUTABLE STRICT AS 'SELECT position(needle in haystack)';
CREATE OR REPLACE FUNCTION json_extract(document TEXT, json_path TEXT) RETURNS TEXT
  LANGUAGE SQL IMMUTABLE STRICT AS $$ SELECT document::jsonb #>> string_to_array(substr(json_path,3),'.') $$;
CREATE OR REPLACE FUNCTION labos_date(value TEXT) RETURNS DATE
  LANGUAGE plpgsql IMMUTABLE STRICT AS $$ BEGIN RETURN value::timestamptz AT TIME ZONE 'UTC';
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,role TEXT);CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id BIGINT,expires_at BIGINT);CREATE TABLE IF NOT EXISTS records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,module TEXT,title TEXT NOT NULL,code TEXT,status TEXT,category TEXT,owner TEXT,due_date TEXT,amount DOUBLE PRECISION DEFAULT 0,quantity DOUBLE PRECISION DEFAULT 0,data TEXT DEFAULT '{}',created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),updated_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),deleted_at TEXT DEFAULT '',version BIGINT NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,record_id BIGINT,original_name TEXT,stored_name TEXT,mime_type TEXT,size BIGINT,created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT,action TEXT,entity TEXT,entity_id BIGINT,detail TEXT,created_at TEXT DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));CREATE TABLE IF NOT EXISTS nav_items(key TEXT PRIMARY KEY,label TEXT NOT NULL,icon TEXT DEFAULT '□',description TEXT DEFAULT '',target TEXT NOT NULL,sort_order BIGINT DEFAULT 0,visible BIGINT DEFAULT 1);CREATE TABLE IF NOT EXISTS dashboard_items(key TEXT PRIMARY KEY,label TEXT NOT NULL,description TEXT DEFAULT '',kind TEXT NOT NULL,target TEXT NOT NULL,sort_order BIGINT DEFAULT 0,visible BIGINT DEFAULT 1);CREATE TABLE IF NOT EXISTS role_permissions(role TEXT PRIMARY KEY,permissions TEXT NOT NULL DEFAULT '[]');CREATE TABLE IF NOT EXISTS schema_migrations(name TEXT PRIMARY KEY,applied_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));

    CREATE TABLE IF NOT EXISTS material_categories(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE,
      created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_regions(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE,
      created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_catalog(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL,
      spec TEXT NOT NULL, unit TEXT NOT NULL, category_id BIGINT NOT NULL REFERENCES material_categories(id),
      tracking_mode TEXT NOT NULL DEFAULT 'quantity' CHECK(tracking_mode IN ('quantity','unit')),
      version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
      created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_barcodes(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE "C" CHECK(length(code)>0 AND length(code)<=512),
      catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), created_by BIGINT NOT NULL REFERENCES users(id),
      created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_requests(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, no TEXT NOT NULL UNIQUE, title TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted')),
      created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),
      submitted_by BIGINT REFERENCES users(id), submitted_at TEXT,
      version BIGINT NOT NULL DEFAULT 1 CHECK(version>0), revision BIGINT NOT NULL DEFAULT 0 CHECK(revision>=0),
      original_snapshot TEXT
    );
    CREATE TABLE IF NOT EXISTS material_request_items(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES material_requests(id),
      catalog_id BIGINT REFERENCES material_catalog(id), code TEXT NOT NULL DEFAULT '', name TEXT NOT NULL,
      spec TEXT NOT NULL, unit TEXT NOT NULL, category_id BIGINT NOT NULL REFERENCES material_categories(id),
      region_id BIGINT NOT NULL REFERENCES material_regions(id), warehouse TEXT NOT NULL,
      qty_m BIGINT NOT NULL CHECK(qty_m>0), purpose TEXT NOT NULL DEFAULT '',
      author_id BIGINT NOT NULL REFERENCES users(id), version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
      created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_request_revisions(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL REFERENCES material_requests(id),
      revision BIGINT NOT NULL CHECK(revision>=2), before_snapshot TEXT NOT NULL, after_snapshot TEXT NOT NULL,
      reason TEXT NOT NULL, actor_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),
      UNIQUE(request_id,revision)
    );
    CREATE TABLE IF NOT EXISTS material_receipts(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('acceptance','rejection','close','reversal')),
      request_id BIGINT NOT NULL REFERENCES material_requests(id), item_id BIGINT NOT NULL REFERENCES material_request_items(id),
      request_revision BIGINT NOT NULL, snapshot TEXT NOT NULL,
      qty_m BIGINT NOT NULL DEFAULT 0, rejected_qty_m BIGINT NOT NULL DEFAULT 0 CHECK(rejected_qty_m>=0),
      closed_qty_m BIGINT NOT NULL DEFAULT 0 CHECK(closed_qty_m>=0), amount_cents BIGINT NOT NULL DEFAULT 0,
      reason TEXT NOT NULL DEFAULT '', rejected_reason TEXT NOT NULL DEFAULT '', zero_amount_reason TEXT NOT NULL DEFAULT '',
      original_receipt_id BIGINT REFERENCES material_receipts(id), batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '',
      date TEXT NOT NULL, actor_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),
      CHECK((type='acceptance' AND qty_m>0 AND amount_cents>=0) OR
        (type='rejection' AND qty_m=0 AND amount_cents=0 AND rejected_qty_m>0) OR
        (type='close' AND qty_m=0 AND amount_cents=0 AND closed_qty_m>0) OR
        (type='reversal' AND qty_m<0 AND amount_cents<=0 AND original_receipt_id IS NOT NULL))
    );
    CREATE UNIQUE INDEX IF NOT EXISTS material_one_reversal ON material_receipts(original_receipt_id) WHERE type='reversal';
    CREATE TABLE IF NOT EXISTS material_stock_locations(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), region_id BIGINT NOT NULL REFERENCES material_regions(id),
      warehouse TEXT NOT NULL, batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '',
      location TEXT NOT NULL CHECK(length(location)<=200), version BIGINT NOT NULL CHECK(version>0),
      reason TEXT NOT NULL, actor_id BIGINT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL,
      UNIQUE(catalog_id,warehouse,region_id,batch,expiry_date)
    );
    CREATE TABLE IF NOT EXISTS material_issues(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','issued','rejected','cancelled')),
      version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
      catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), region_id BIGINT NOT NULL REFERENCES material_regions(id),
      warehouse TEXT NOT NULL, batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '',
      qty_m BIGINT NOT NULL CHECK(qty_m>0), amount_cents BIGINT NOT NULL DEFAULT 0 CHECK(amount_cents>=0),
      snapshot TEXT NOT NULL, purpose TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '',
      created_by BIGINT NOT NULL REFERENCES users(id), processed_by BIGINT REFERENCES users(id),
      created_at TEXT NOT NULL, processed_at TEXT
    );
    CREATE TABLE IF NOT EXISTS material_stock_movements(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('opening','receipt','reversal','adjustment','issue')),
      catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), region_id BIGINT NOT NULL REFERENCES material_regions(id),
      warehouse TEXT NOT NULL, qty_m BIGINT NOT NULL CHECK(qty_m<>0), amount_cents BIGINT NOT NULL,
      receipt_id BIGINT REFERENCES material_receipts(id), source_key TEXT NOT NULL UNIQUE, snapshot TEXT NOT NULL,
      batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '', date TEXT NOT NULL,
      reason TEXT NOT NULL DEFAULT '', actor_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS'))
    );
    CREATE TABLE IF NOT EXISTS material_openings(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, no TEXT NOT NULL UNIQUE, title TEXT NOT NULL, date TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL CHECK(kind IN ('opening','supplement')),
      reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')),
      version BIGINT NOT NULL DEFAULT 1 CHECK(version>0), created_by BIGINT NOT NULL REFERENCES users(id),
      created_at TEXT NOT NULL, posted_by BIGINT REFERENCES users(id), posted_at TEXT,
      CHECK((status='draft' AND posted_by IS NULL AND posted_at IS NULL) OR
        (status='posted' AND posted_by IS NOT NULL AND posted_at IS NOT NULL))
    );
    CREATE TABLE IF NOT EXISTS material_opening_items(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, opening_id BIGINT NOT NULL REFERENCES material_openings(id),
      catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), region_id BIGINT NOT NULL REFERENCES material_regions(id),
      warehouse TEXT NOT NULL, qty_m BIGINT NOT NULL CHECK(qty_m>0), amount_cents BIGINT NOT NULL CHECK(amount_cents>=0),
      batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '',
      location_version BIGINT NOT NULL CHECK(location_version>=0), zero_amount_reason TEXT NOT NULL DEFAULT '',
      snapshot TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1 CHECK(version>0),
      movement_id BIGINT UNIQUE REFERENCES material_stock_movements(id)
    );
    CREATE TABLE IF NOT EXISTS material_attachments(
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT REFERENCES material_requests(id),
      receipt_id BIGINT REFERENCES material_receipts(id), name TEXT NOT NULL, mime_type TEXT NOT NULL,
      stored_name TEXT NOT NULL UNIQUE, size BIGINT NOT NULL CHECK(size>0 AND size<=5242880),
      active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
      actor_id BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),
      CHECK((request_id IS NOT NULL AND receipt_id IS NULL) OR (request_id IS NULL AND receipt_id IS NOT NULL))
    );
    CREATE TABLE IF NOT EXISTS material_state(key TEXT PRIMARY KEY, value TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS material_idempotency(
      actor_id BIGINT NOT NULL REFERENCES users(id), key TEXT NOT NULL, digest TEXT NOT NULL,
      response TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')), PRIMARY KEY(actor_id,key)
    );
    CREATE INDEX IF NOT EXISTS material_request_status ON material_requests(status,created_at);
    CREATE INDEX IF NOT EXISTS material_items_request ON material_request_items(request_id);
    CREATE INDEX IF NOT EXISTS material_receipt_item ON material_receipts(item_id,id);
    CREATE INDEX IF NOT EXISTS material_stock_key ON material_stock_movements(catalog_id,warehouse,region_id);
    CREATE INDEX IF NOT EXISTS material_attachment_request ON material_attachments(request_id,receipt_id);
    CREATE INDEX IF NOT EXISTS material_issue_owner ON material_issues(created_by,status,id);
    CREATE INDEX IF NOT EXISTS material_opening_item_parent ON material_opening_items(opening_id,id);

CREATE TABLE IF NOT EXISTS material_stock_units(
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE "C" CHECK(length(code)>0 AND length(code)<=128),
    sequence BIGINT NOT NULL UNIQUE CHECK(sequence>0),
    catalog_id BIGINT NOT NULL REFERENCES material_catalog(id), region_id BIGINT NOT NULL REFERENCES material_regions(id),
    warehouse TEXT NOT NULL, batch TEXT NOT NULL DEFAULT '', expiry_date TEXT NOT NULL DEFAULT '',
    source_movement_id BIGINT NOT NULL REFERENCES material_stock_movements(id),
    exit_movement_id BIGINT REFERENCES material_stock_movements(id),
    status TEXT NOT NULL DEFAULT 'in_stock' CHECK(status IN ('in_stock','issued','void')),
    created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL,
    CHECK((status='in_stock' AND exit_movement_id IS NULL) OR (status IN ('issued','void') AND exit_movement_id IS NOT NULL))
  );
  CREATE INDEX IF NOT EXISTS material_unit_batch ON material_stock_units(catalog_id,region_id,warehouse,batch,expiry_date,status);
  CREATE INDEX IF NOT EXISTS material_unit_source ON material_stock_units(source_movement_id);
  CREATE INDEX IF NOT EXISTS material_unit_exit ON material_stock_units(exit_movement_id);
-- Retired native-printing storage: retain schema and rows for existing database backups.
-- No application API reads, claims, expires or changes these historical tasks.
CREATE TABLE IF NOT EXISTS printing_templates(
  id TEXT PRIMARY KEY, name TEXT NOT NULL, file_name TEXT NOT NULL, sha256 TEXT NOT NULL,
  size BIGINT NOT NULL CHECK(size>0 AND size<=4194304), content_base64 TEXT NOT NULL, fields TEXT NOT NULL,
  active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS printing_stations(
  id TEXT PRIMARY KEY, name TEXT NOT NULL, printer_name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE,
  enabled BIGINT NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), created_by BIGINT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL, last_seen_at TEXT, agent_version TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS printing_jobs(
  id TEXT PRIMARY KEY, station_id TEXT NOT NULL REFERENCES printing_stations(id), station_name TEXT NOT NULL, printer_name TEXT NOT NULL,
  template_id TEXT NOT NULL REFERENCES printing_templates(id), template_name TEXT NOT NULL, template_file_name TEXT NOT NULL,
  template_sha256 TEXT NOT NULL, template_content_base64 TEXT NOT NULL, template_fields TEXT NOT NULL,
  unit_ids TEXT NOT NULL, rows_snapshot TEXT NOT NULL, row_count BIGINT NOT NULL CHECK(row_count>0 AND row_count<=1000),
  status TEXT NOT NULL CHECK(status IN ('queued','claimed','printing','submitted','failed','unknown','cancelled','confirmed')),
  created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  idempotency_key TEXT NOT NULL, payload_digest TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', reprint_of TEXT REFERENCES printing_jobs(id),
  lease_hash TEXT, lease_expires_at BIGINT, message TEXT NOT NULL DEFAULT '', result_status TEXT NOT NULL DEFAULT '', result_message TEXT NOT NULL DEFAULT '',
  confirmed_by BIGINT REFERENCES users(id), confirmed_at TEXT, confirmation_reason TEXT NOT NULL DEFAULT '',
  UNIQUE(created_by,idempotency_key)
);
ALTER TABLE printing_jobs ADD COLUMN IF NOT EXISTS kind TEXT NOT NULL DEFAULT 'print' CHECK(kind IN ('print','preview'));
ALTER TABLE printing_jobs ADD COLUMN IF NOT EXISTS paper TEXT;
ALTER TABLE printing_jobs ADD COLUMN IF NOT EXISTS preview_base64 TEXT CHECK(preview_base64 IS NULL OR length(preview_base64)<=2796204);
CREATE INDEX IF NOT EXISTS printing_job_queue ON printing_jobs(station_id,status,created_at,id);
CREATE INDEX IF NOT EXISTS printing_job_owner ON printing_jobs(created_by,created_at,id);
CREATE UNIQUE INDEX IF NOT EXISTS printing_station_busy ON printing_jobs(station_id) WHERE status IN ('claimed','printing');
CREATE OR REPLACE FUNCTION labos_quality_current() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.module='quality' AND NEW.data::jsonb->>'is_current'='是' AND COALESCE(NEW.deleted_at,'')='' THEN
    UPDATE records SET data=jsonb_set(data::jsonb,'{is_current}','"否"'::jsonb)::text,
      version=version+1,updated_at=to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')
      WHERE module='quality' AND id<>NEW.id AND title=NEW.title
      AND data::jsonb->>'quality_section'=NEW.data::jsonb->>'quality_section'
      AND data::jsonb->>'is_current'='是' AND COALESCE(deleted_at,'')='';
  END IF;
  RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS quality_current ON records;
CREATE TRIGGER quality_current AFTER INSERT OR UPDATE OF data,title,deleted_at ON records
  FOR EACH ROW EXECUTE FUNCTION labos_quality_current();
